<script setup lang="ts">
import { ref, reactive, onMounted, watch, onUnmounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, type User } from '../api'
import { useSession } from '../session'
import { captureRequestScope } from '../request-scope'
import EmployeeCreate from './EmployeeCreate.vue'
const auth = useSession(), route = useRoute(), router = useRouter()
const rows = ref<User[]>([]), total = ref(0), loading = ref(false), failed = ref(''), filter = reactive({ account: '', status: '' }), page = ref(1), size = ref(20)
let serial = 0
function fromQuery() { filter.account = typeof route.query.account === 'string' ? route.query.account : ''; filter.status = ['0','1'].includes(String(route.query.status)) ? String(route.query.status) : ''; const value = Number(route.query.page); page.value = Number.isSafeInteger(value) && value >= 1 && value <= 1000000 ? value : 1; size.value = [20,50,100].includes(Number(route.query.size)) ? Number(route.query.size) : 20 }
async function load() { const n = ++serial, path = route.fullPath; const scope = captureRequestScope(auth, () => n === serial && route.fullPath === path); rows.value = []; total.value = 0; loading.value = true; failed.value = ''; try { const query = new URLSearchParams({ page: String(page.value), size: String(size.value) }); if (filter.account) query.set('keyword', filter.account); if (filter.status) query.set('status', filter.status); const result = await api.users(query); if (!scope.current()) return; rows.value = result.items; total.value = result.total } catch (e) { if (!scope.current()) return; failed.value = '列表加载失败，请重试。'; auth.handleFailure(e) } finally { if (scope.current()) loading.value = false } }
function query(reset = true) { if (reset) page.value = 1; void router.replace({ path: '/users', query: { ...(filter.account ? { account: filter.account } : {}), ...(filter.status ? { status: filter.status } : {}), page: page.value, size: size.value } }) }
watch(() => route.fullPath, () => { fromQuery(); void load() }); onMounted(() => { fromQuery(); void load() }); onUnmounted(() => { serial++ })
</script>
<template><section class="page-heading"><p class="eyebrow">SESSION ADMINISTRATION</p><h1>{{ auth.identity?.realm === 'PLATFORM' ? '平台账号' : '租户用户' }}</h1><p>当前命名空间内的账号与员工管理，不会返回其他租户账号。</p></section><section class="panel"><form class="filters" @submit.prevent="query()"><div><label for="search">账号关键字</label><el-input id="search" v-model="filter.account" clearable /></div><div><label for="status">状态</label><el-select id="status" v-model="filter.status" placeholder="全部" clearable><el-option label="启用" value="1" /><el-option label="停用" value="0" /></el-select></div><el-button type="primary" native-type="submit">查询</el-button><el-button @click="filter.account=''; filter.status=''; query()">清空</el-button><el-button :loading="loading" @click="load">刷新</el-button></form><p v-if="failed" role="alert" class="field-error">{{ failed }}</p><div v-if="!failed" class="table-wrap" v-loading="loading"><el-table :data="rows" empty-text="当前条件没有记录" :aria-busy="loading"><el-table-column prop="account" label="账号" /><el-table-column prop="displayName" label="姓名" /><el-table-column prop="identityType" label="身份" /><el-table-column label="状态"><template #default="{ row }">{{ row.status === 1 || row.status === 'ENABLED' ? '启用' : '停用' }}</template></el-table-column><el-table-column label="需改密"><template #default="{ row }">{{ row.mustChangePassword ? '是' : '否' }}</template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button link type="primary" @click="$router.push('/users/'+row.id)">查看详情</el-button></template></el-table-column></el-table></div><el-pagination v-if="!failed" class="pagination" v-model:current-page="page" v-model:page-size="size" :page-sizes="[20,50,100]" :total="total" layout="total, sizes, prev, pager, next" @current-change="query(false)" @size-change="query()" /></section><EmployeeCreate @created="id => router.push('/users/'+id)" /></template>

